INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.106.0',
  '2026-10-01',
  'Игры: 2048, пятнашки и «найди пару»',
  E'Новая страница «Игры» — чем занять голову вечером, не выходя из приложения. Три игры: 2048 (двигаете плитки, одинаковые складываются), пятнашки и «найди пару».\n\nРекорды хранятся на сервере, поэтому видны с любого устройства: у 2048 это очки и лучшая плитка, у пятнашек и пар — время и число ходов. Недоигранная партия 2048 ждёт на том же телефоне, где вы её бросили, а если выйти из партии посреди игры, счёт всё равно засчитается.\n\nВо вкладке «Настройки» под каждую игру выбираются свои картинки — те же, что лежат в «Оформление → Фон приложения», копии не создаются, и место они занимают один раз. При каждом запуске картинка берётся из набора случайно: в 2048 она становится фоном поля, в пятнашках разрезается на костяшки (собирать картинку интереснее, чем числа), в «найди пару» становится рубашкой карт. Загрузить новую можно прямо оттуда.\n\nВкладка «С друзьями» пока пустая: там появятся игры вдвоём по переписке — сделали ход, и бот позвал соперника в Telegram. Первыми будут крестики-нолики и морской бой.',
  E'Страница целиком на клиенте: внешних библиотек и ассетов нет, поля — вёрстка, карты «найди пару» — эмодзи. Игра это компонент, а не роут: внутри партии нужна кнопка «К играм», а не шаг назад в истории.\n\nМиграция 0154: game_scores (user_id, game, best, detail, played) и game_backgrounds (user_id, game, image_id → user_backgrounds ON DELETE CASCADE). Что считается лучшим результатом, знает gameRules в httpapi/games.go (2048 — больше очков, пятнашки и пары — меньше секунд); сравнение делает сам INSERT … ON CONFLICT через GREATEST/LEAST, чтобы два устройства подряд не затирали друг друга чтением-записью, а detail меняется только вместе с рекордом. Картинки под игру — ссылки на фоны пользователя, а не копии: удалённая в «Оформлении» картинка пропадает и из игр, висячих ссылок не остаётся. Регистрация страницы: PagesRegistry, guardedPages, pageDataSources (game_scores), роут с meta.version, раздел в HelpView.\n\nПятнашки перемешиваются сотней случайных ходов от собранного состояния — случайная перестановка в половине случаев нерешаема. Кусок картинки на костяшке: background-size 400% и позиция по номеру костяшки, а не по её месту на поле. Незаконченная партия 2048 — в localStorage устройства; при выходе с ненулевым счётом результат отправляется на сервер. Миниатюра для загрузки вынесена из BackgroundPicker в shared/background.ts (makeImageThumb), добавлены haptic()/hapticNotify() в shared/telegram.ts.\n\nПроверено: правила рекордов (2048 держит максимум, пятнашки минимум, чужая игра — 400), набор картинок игры (чужой id не вставляется), в браузере — ходы и склейка плиток в 2048 с сохранением партии, ход и таймер в пятнашках с картинкой на костяшках, полная партия «найди пару» до победы с записью рекорда, выбор картинки в настройках и её появление под полем 2048.'
);
-- +goose StatementEnd

